// TiersMode says how a metered plan's tiers price the usage.
type TiersMode string

// Tier modes.
const (
	// Graduated prices each unit at the tier it falls in: the first tier's units, then the next tier's, and so on.
	Graduated TiersMode = "graduated"
	// Volume prices every unit at the one tier the total usage falls in.
	Volume TiersMode = "volume"
)

// Valid reports whether m is a known tier mode.
func (m TiersMode) Valid() bool { return m == Graduated || m == Volume }

// Tier is one band of a tiered metered plan. Its amounts are minor units. UpTo is the last unit the tier covers (inclusive);
// nil means no limit, and only the last tier has it.
type Tier struct {
	UpTo       *int64 `json:"up_to"`
	UnitAmount int64  `json:"unit_amount"`
	FlatAmount int64  `json:"flat_amount"`
}

// Plan is something an organization sells to its customers.
type Plan struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	Currency   money.Currency `json:"currency"`
	UnitAmount int64          `json:"unit_amount"` // minor units
	Interval   Interval       `json:"interval"`
	UsageType  UsageType      `json:"usage_type"`
	// TiersMode and Tiers price a metered plan by tier instead of UnitAmount. A tiered plan's UnitAmount is 0.
	TiersMode TiersMode `json:"tiers_mode"`
	Tiers     []Tier    `json:"tiers"`
	TrialDays int       `json:"trial_days"`
	Active    bool      `json:"active"`
	CreatedAt time.Time `json:"created_at"`
}

// Tiered reports whether the plan is priced by tiers.
func (p Plan) Tiered() bool { return len(p.Tiers) > 0 }

