func TestTieredPlans(t *testing.T) {
	e := apitest.New(t)
	type planOut struct {
		store.Plan
		Price string `json:"price"`
	}
	tiers := []map[string]any{
		{"up_to": 10, "unit_amount": "1.00"},
		{"up_to": 100, "unit_amount": "0.50", "flat_amount": "5.00"},
		{"up_to": nil, "unit_amount": "0.20"},
	}
	var p planOut
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "API", "currency": "USD", "interval": "month",
		"usage_type": "metered", "tiers_mode": "graduated", "tiers": tiers}, &p)
	if p.UsageType != store.Metered || p.TiersMode != store.Graduated || p.UnitAmount != 0 || len(p.Tiers) != 3 {
		t.Fatalf("plan = %+v", p)
	}
	if p.Tiers[0].UpTo == nil || *p.Tiers[0].UpTo != 10 || p.Tiers[0].UnitAmount != 100 || p.Tiers[0].FlatAmount != 0 ||
		p.Tiers[1].FlatAmount != 500 || p.Tiers[2].UpTo != nil || p.Tiers[2].UnitAmount != 20 {
		t.Fatalf("tiers = %+v (amounts are minor units)", p.Tiers)
	}
	var got planOut
	e.MustDo(http.StatusOK, "GET", "/v1/plans/"+p.ID, e.Acme.Key, nil, &got)
	if got.TiersMode != store.Graduated || len(got.Tiers) != 3 || got.Tiers[1].UnitAmount != 50 {
		t.Fatalf("GET plan = %+v", got)
	}

	invalid := map[string]map[string]any{
		"tiers on a licensed plan": {"usage_type": "licensed", "tiers_mode": "volume", "tiers": tiers},
		"no tiers_mode":            {"usage_type": "metered", "tiers": tiers},
		"unknown tiers_mode":       {"usage_type": "metered", "tiers_mode": "flat", "tiers": tiers},
		"no tiers":                 {"usage_type": "metered", "tiers_mode": "volume", "tiers": []any{}},
		"tiers_mode alone":         {"usage_type": "metered", "tiers_mode": "volume"},
		"not ascending": {"usage_type": "metered", "tiers_mode": "volume", "tiers": []any{
			map[string]any{"up_to": 10, "unit_amount": "1"}, map[string]any{"up_to": 5, "unit_amount": "1"}, map[string]any{"up_to": nil, "unit_amount": "1"}}},
		"last tier has a limit": {"usage_type": "metered", "tiers_mode": "volume", "tiers": []any{map[string]any{"up_to": 10, "unit_amount": "1"}}},
		"fractional up_to": {"usage_type": "metered", "tiers_mode": "volume", "tiers": []any{
			map[string]any{"up_to": 1.5, "unit_amount": "1"}, map[string]any{"up_to": nil, "unit_amount": "1"}}},
		"negative amount": {"usage_type": "metered", "tiers_mode": "volume", "tiers": []any{
			map[string]any{"up_to": nil, "unit_amount": "-1"}}},
		"bad amount": {"usage_type": "metered", "tiers_mode": "volume", "tiers": []any{
			map[string]any{"up_to": nil, "unit_amount": "abc"}}},
	}
	for name, body := range invalid {
		body["name"], body["currency"], body["interval"] = "X", "USD", "month"
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_tiers" {
			t.Errorf("%s: %s", name, r)
		}
	}
}

func TestMeteredPlanStillNeedsAPrice(t *testing.T) {
	e := apitest.New(t)
	if r := e.Do("POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "X", "currency": "USD", "interval": "month", "usage_type": "metered"}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_amount" {
		t.Fatalf("metered without price or tiers: %s", r)
	}
}
